# Generated by build.py from recipe.yml for recipe http-serve-a-small-website. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'site/css', 'site/js', 'site/img', 'site/data', 'site/downloads', 'site/fonts' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/index.html'), "<!doctype html><title>Home</title><link rel=stylesheet href=css/site.css><script src=js/app.js></script><img src=img/logo.png>`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/css/site.css'), "body { margin: 0; }`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/js/app.js'), "console.log('loaded');`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/img/logo.png'), "not really a PNG`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/img/icon.svg'), "<svg xmlns='http://www.w3.org/2000/svg'/>`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/data/menu.json'), "{`"items`": []}`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/downloads/notes.xyz'), "an extension surl does not know`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/downloads/README'), "no extension at all`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/img/photo.jpg'), "not really a JPEG`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/favicon.ico'), "not really an icon`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/fonts/body.woff2'), "not really a font`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/js/module.mjs'), "export {};`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --remote-name-all --create-dirs --output-dir fetched -w "%{url.path} %{http_code} %{content_type}\n" http://127.0.0.1:8080/index.html http://127.0.0.1:8080/css/site.css http://127.0.0.1:8080/js/app.js http://127.0.0.1:8080/img/logo.png http://127.0.0.1:8080/img/icon.svg http://127.0.0.1:8080/data/menu.json } finally { Stop-Process $server0 }
